// Appends Infection Control ids 101-150
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const T=`"Infection Control & Sanitation"`, Tes=`"Control de Infecciones y Saneamiento"`, PT=`"Infection Control"`, PTes=`"Control de Infecciones"`
function fmt(q) {
  return `  { id: ${q.id}, topic: ${T}, topic_es: ${Tes}, psi_topic: ${PT}, psi_topic_es: ${PTes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const Q = [
  { id: 101, question: "Phenolic compounds used as disinfectants in esthetics establishments are effective against:", question_es: "Los compuestos fenólicos usados como desinfectantes en establecimientos de estética son efectivos contra:", options: ["A broad spectrum of pathogens including bacteria, viruses (including HIV and hepatitis B), and fungi — making them a common choice for implement and surface disinfection in esthetics", "Only bacteria — phenolics have no activity against viruses or fungi", "Only surfaces — phenolics cannot be used for implement disinfection", "Only when diluted to 50% concentration — higher concentrations are prohibited in Texas"], options_es: ["Un amplio espectro de patógenos incluidos bacterias, virus (incluidos el VIH y la hepatitis B) y hongos — lo que los convierte en una opción común para la desinfección de implementos y superficies en estética", "Solo bacterias — los fenólicos no tienen actividad contra virus u hongos", "Solo superficies — los fenólicos no pueden usarse para la desinfección de implementos", "Solo cuando se diluyen al 50% de concentración — las concentraciones más altas están prohibidas en Texas"], correct: 0, explanation: "Phenolic disinfectants are broad-spectrum and effective against many bacteria, mycobacteria, viruses, and fungi. They are commonly used for implement soaking in esthetics. They must be used at manufacturer-specified concentrations and require adequate contact time. Some phenolics can damage certain plastics and rubber." },
  { id: 102, question: "A 'tuberculocidal' disinfectant is significant in esthetics because:", question_es: "Un desinfectante 'tuberculicida' es significativo en la estética porque:", options: ["Tuberculocidal activity means the disinfectant is effective against Mycobacterium tuberculosis — one of the most resistant non-spore-forming bacteria — so a tuberculocidal disinfectant provides a broad level of protection for esthetics implements", "Tuberculosis is a common condition in esthetics clients requiring specific treatment protocols", "Only medical facilities are required to use tuberculocidal disinfectants — esthetics establishments may use lower-level products", "Tuberculocidal disinfectants are specifically for air filtration systems, not implement disinfection"], options_es: ["La actividad tuberculicida significa que el desinfectante es efectivo contra Mycobacterium tuberculosis — una de las bacterias resistentes no esporuladas más comunes — por lo que un desinfectante tuberculicida proporciona un amplio nivel de protección para los implementos de estética", "La tuberculosis es una condición común en clientes de estética que requiere protocolos de tratamiento específicos", "Solo las instalaciones médicas están obligadas a usar desinfectantes tuberculicidas — los establecimientos de estética pueden usar productos de menor nivel", "Los desinfectantes tuberculicidas son específicamente para sistemas de filtración de aire, no para la desinfección de implementos"], correct: 0, explanation: "Mycobacterium tuberculosis is very resistant to disinfection. The ability to kill M. tuberculosis is used as a benchmark for intermediate-level disinfection. Tuberculocidal disinfectants (most quaternary ammonium and phenolic products that are properly formulated) provide confidence against many other, less-resistant pathogens as well." },
  { id: 103, question: "The Spaulding Classification System categorizes implements into critical, semi-critical, and non-critical. In an esthetics context:", question_es: "El Sistema de Clasificación de Spaulding categoriza los implementos en críticos, semi-críticos y no críticos. En el contexto de la estética:", options: ["Critical items (penetrate skin — lancets, needles) require sterilization; semi-critical items (contact non-intact skin — extractors, spatulas) require high-level disinfection; non-critical items (contact intact skin) require low-to-intermediate disinfection", "All esthetics implements are non-critical and require only sanitization (soap and water)", "All esthetics implements are critical and must be sterilized in an autoclave after each use", "The Spaulding system only applies to medical devices and has no relevance to esthetics practice"], options_es: ["Los artículos críticos (que penetran la piel — lancetas, agujas) requieren esterilización; los artículos semi-críticos (que contactan piel no intacta — extractores, espátulas) requieren desinfección de alto nivel; los artículos no críticos (que contactan piel intacta) requieren desinfección de nivel bajo a intermedio", "Todos los implementos de estética son no críticos y requieren solo saneamiento (jabón y agua)", "Todos los implementos de estética son críticos y deben esterilizarse en un autoclave después de cada uso", "El sistema de Spaulding solo aplica a dispositivos médicos y no tiene relevancia para la práctica de estética"], correct: 0, explanation: "The Spaulding Classification guides decontamination level selection. In esthetics: lancets/needles (critical) → sterilize/single-use; extractors, comedone tools (semi-critical — may contact compromised skin) → high-level disinfection; facial brushes, spatulas used on intact skin (non-critical) → intermediate disinfection. Understanding this guides appropriate sanitation decisions." },
  { id: 104, question: "HIV (Human Immunodeficiency Virus) transmission in an esthetics establishment is prevented by:", question_es: "La transmisión del VIH (Virus de Inmunodeficiencia Humana) en un establecimiento de estética se previene mediante:", options: ["Standard precautions — wearing gloves when contact with blood or body fluids is possible, proper hand washing, and using EPA-registered disinfectants known to inactivate HIV on implements and surfaces", "Requiring all clients to disclose HIV status before receiving services — HIV-positive clients are denied service", "HIV cannot survive outside the body, so no special precautions are needed in esthetics", "Only autoclaving implements prevents HIV transmission — disinfection is insufficient against HIV"], options_es: ["Precauciones estándar — usar guantes cuando sea posible el contacto con sangre o fluidos corporales, lavado de manos adecuado y usar desinfectantes registrados por la EPA que se sabe inactivan el VIH en implementos y superficies", "Requerir que todos los clientes divulguen el estado de VIH antes de recibir servicios — los clientes VIH-positivos son negados del servicio", "El VIH no puede sobrevivir fuera del cuerpo, por lo que no se necesitan precauciones especiales en la estética", "Solo la esterilización con autoclave evita la transmisión del VIH — la desinfección es insuficiente contra el VIH"], correct: 0, explanation: "HIV is a bloodborne pathogen. Standard precautions protect against HIV by treating all blood and body fluids as potentially infectious. HIV is actually a relatively fragile virus outside the body and is inactivated by many EPA-registered disinfectants. Denying service to HIV-positive clients is discriminatory and illegal under ADA." },
  { id: 105, question: "Hepatitis B virus (HBV) is more dangerous than HIV in esthetics settings because:", question_es: "El virus de la hepatitis B (VHB) es más peligroso que el VIH en los entornos de estética porque:", options: ["HBV is far more hardy than HIV outside the body — it can survive on dry surfaces for up to 7 days, is more concentrated in blood, and is much more easily transmitted through accidental blood contact on implements", "HIV is always more dangerous than HBV in any setting", "HBV is only transmitted through sexual contact, not through esthetics implements", "HBV poses no risk in esthetics because the hepatitis B vaccine is 100% effective at preventing any transmission"], options_es: ["El VHB es mucho más resistente que el VIH fuera del cuerpo — puede sobrevivir en superficies secas hasta 7 días, está más concentrado en la sangre y se transmite mucho más fácilmente a través del contacto accidental con sangre en los implementos", "El VIH siempre es más peligroso que el VHB en cualquier entorno", "El VHB solo se transmite a través del contacto sexual, no a través de implementos de estética", "El VHB no presenta ningún riesgo en la estética porque la vacuna contra la hepatitis B es 100% efectiva para prevenir cualquier transmisión"], correct: 0, explanation: "HBV survives on environmental surfaces for up to 7 days. It is 50–100 times more infectious than HIV through needlestick/sharps injuries. Blood on unclean implements presents a serious HBV transmission risk. The HBV vaccine is highly effective but estheticians should still follow standard precautions regardless of vaccination status." },
  { id: 106, question: "An exposure incident in an esthetics establishment (such as a needlestick with a lancet) requires:", question_es: "Un incidente de exposición en un establecimiento de estética (como un pinchazo con una lanceta) requiere:", options: ["Immediate first aid (wash the wound thoroughly with soap and water), reporting to the employer, documentation, and seeking post-exposure medical evaluation — including assessment for HBV, HCV, and HIV exposure", "Only bandaging the wound and continuing the service", "Filing a police report within 24 hours of the incident", "Only monitoring for symptoms — medical evaluation is only needed if symptoms appear"], options_es: ["Primeros auxilios inmediatos (lavar la herida a fondo con jabón y agua), informar al empleador, documentación y buscar evaluación médica post-exposición — incluyendo evaluación de exposición a VHB, VHC y VIH", "Solo vender la herida y continuar el servicio", "Presentar un informe policial dentro de las 24 horas del incidente", "Solo monitorear los síntomas — la evaluación médica solo es necesaria si aparecen síntomas"], correct: 0, explanation: "OSHA's Bloodborne Pathogen Standard requires that any exposure incident be treated as a medical emergency for documentation and post-exposure evaluation. Immediate first aid, employer notification, incident documentation, and timely medical evaluation (within hours, not days) are all required steps in the exposure incident protocol." },
  { id: 107, question: "An esthetics establishment's exposure control plan (required by OSHA's Bloodborne Pathogen Standard) must include:", question_es: "El plan de control de exposición de un establecimiento de estética (requerido por el Estándar de Patógenos de Transmisión Sanguínea de OSHA) debe incluir:", options: ["A list of job classifications and tasks involving bloodborne pathogen exposure risk, engineering controls (sharps containers), work practice controls (hand washing, no recapping), PPE requirements, training, and hepatitis B vaccination provisions", "Only the name and phone number of the nearest hospital", "A list of all client names who disclosed bloodborne pathogen infections", "Only the type of disinfectant used in the establishment — no other documentation is required"], options_es: ["Una lista de clasificaciones de trabajo y tareas que involucran riesgo de exposición a patógenos de transmisión sanguínea, controles de ingeniería (contenedores de objetos cortantes), controles de práctica laboral (lavado de manos, sin volver a tapar), requisitos de EPP, capacitación y disposiciones de vacunación contra la hepatitis B", "Solo el nombre y número de teléfono del hospital más cercano", "Una lista de todos los nombres de clientes que divulgaron infecciones de patógenos de transmisión sanguínea", "Solo el tipo de desinfectante usado en el establecimiento — no se requiere otra documentación"], correct: 0, explanation: "OSHA requires a written Exposure Control Plan (ECP) for workplaces with occupational bloodborne pathogen exposure risk. The ECP must cover: hazard determination, engineering/work practice controls, PPE, housekeeping, HBV vaccination, post-exposure evaluation procedures, training, and recordkeeping. It must be reviewed and updated annually." },
  { id: 108, question: "When no puncture-resistant sharps container is available and a lancet must be recapped:", question_es: "Cuando no hay un contenedor de objetos cortantes resistente a pinchazos disponible y se debe volver a tapar una lanceta:", options: ["Recapping should be avoided entirely — use the one-handed scoop technique or a mechanical recapping device if recapping is absolutely necessary, but the lancet should be discarded in an approved sharps container immediately after use without recapping", "Two-handed recapping is always the safest method to avoid dropping the cap", "Simply place the lancet in the regular trash bin if a sharps container is not available — any rigid container is acceptable in an emergency", "Wrap the lancet in paper towels before placing it in the regular trash — this is the OSHA-approved alternative"], options_es: ["El re-tapado debe evitarse por completo — use la técnica de una mano o un dispositivo mecánico de re-tapado si el re-tapado es absolutamente necesario, pero la lanceta debe desecharse en un contenedor de objetos cortantes aprobado inmediatamente después de su uso sin re-tapar", "El re-tapado con dos manos siempre es el método más seguro para evitar dejar caer la tapa", "Simplemente coloque la lanceta en el basurero regular si no hay un contenedor de objetos cortantes disponible — cualquier contenedor rígido es aceptable en una emergencia", "Envuelva la lanceta en toallas de papel antes de colocarla en la basura regular — esta es la alternativa aprobada por OSHA"], correct: 0, explanation: "OSHA prohibits two-handed recapping of sharps (the most common cause of needlestick injuries). If recapping is necessary, use the one-hand scoop method or a mechanical device. Best practice: never recap — immediately discard lancets and needles into an approved sharps container after each single use." },
  { id: 109, question: "Proper ventilation in an esthetics room where chemical peels, waxing, or chemical hair removal services are performed is important because:", question_es: "La ventilación adecuada en una sala de estética donde se realizan peels químicos, encerado o servicios de depilación química es importante porque:", options: ["Chemical fumes and volatile organic compounds (VOCs) from skin care chemicals can accumulate to irritating or potentially harmful concentrations in enclosed spaces — ventilation protects both the esthetician and the client", "Ventilation is only important for hair salons that use bleach — esthetics chemicals have no fume hazard", "Good ventilation keeps the room at the correct temperature for chemical products to work effectively", "Ventilation prevents moisture buildup from steam machines only — chemical fumes are not a ventilation concern"], options_es: ["Los vapores químicos y los compuestos orgánicos volátiles (COV) de los químicos para el cuidado de la piel pueden acumularse a concentraciones irritantes o potencialmente dañinas en espacios cerrados — la ventilación protege tanto al esteticista como al cliente", "La ventilación solo es importante para los salones de cabello que usan lejía — los químicos de estética no tienen peligro de vapores", "La buena ventilación mantiene la sala a la temperatura correcta para que los productos químicos funcionen eficazmente", "La ventilación previene la acumulación de humedad de las máquinas de vapor solo — los vapores químicos no son una preocupación de ventilación"], correct: 0, explanation: "Many esthetics chemicals (chemical peels, waxing strips, depilatory creams, toners with alcohols) release fumes. In poorly ventilated rooms, these can accumulate to concentrations that irritate the esthetician's respiratory tract, eyes, or skin over repeated daily exposure. OSHA requires adequate ventilation for chemical hazard areas." },
  { id: 110, question: "Contact dermatitis is relevant to esthetics practice because:", question_es: "La dermatitis de contacto es relevante para la práctica de estética porque:", options: ["Estheticians are at occupational risk for contact dermatitis from repeated exposure to chemicals (disinfectants, product ingredients, wax) and from frequent hand washing — and clients may develop it from esthetics products", "Contact dermatitis only affects clients who are already diagnosed with eczema", "Contact dermatitis is a viral infection transmitted through contaminated implements", "Contact dermatitis is only a legal concern if the client reports it to TDLR"], options_es: ["Los esteticistas tienen riesgo ocupacional de dermatitis de contacto por la exposición repetida a químicos (desinfectantes, ingredientes de productos, cera) y el lavado frecuente de manos — y los clientes pueden desarrollarla por productos de estética", "La dermatitis de contacto solo afecta a clientes que ya tienen diagnóstico de eccema", "La dermatitis de contacto es una infección viral transmitida a través de implementos contaminados", "La dermatitis de contacto solo es una preocupación legal si el cliente la reporta a TDLR"], correct: 0, explanation: "Contact dermatitis (both irritant and allergic types) is an occupational hazard for estheticians exposed to repeated skin contact with chemicals, disinfectants, and wet work. Clients may also develop it from product ingredients. Patch testing before chemical services identifies sensitized clients. PPE (gloves) helps protect the esthetician." },
  { id: 111, question: "Latex allergy is a concern in an esthetics establishment because:", question_es: "La alergia al látex es una preocupación en un establecimiento de estética porque:", options: ["Clients or estheticians with latex allergy can have serious or anaphylactic reactions to latex gloves — latex-free (nitrile, vinyl) gloves must be available and used when latex allergy is known or suspected", "Latex allergy only causes skin rashes and is never life-threatening in an esthetics setting", "Only medical facilities must use non-latex gloves — esthetics establishments are exempt from this requirement", "Latex allergy is a legal concern only if the esthetician has the allergy — client latex allergies are the client's responsibility to manage"], options_es: ["Los clientes o esteticistas con alergia al látex pueden tener reacciones graves o anafilácticas a los guantes de látex — los guantes sin látex (nitrilo, vinilo) deben estar disponibles y usarse cuando se conoce o sospecha la alergia al látex", "La alergia al látex solo causa erupciones cutáneas y nunca pone en peligro la vida en un entorno de estética", "Solo las instalaciones médicas deben usar guantes sin látex — los establecimientos de estética están exentos de este requisito", "La alergia al látex es solo una preocupación legal si el esteticista tiene la alergia — las alergias al látex de los clientes son responsabilidad del cliente"], correct: 0, explanation: "Latex allergy can cause reactions ranging from local urticaria to systemic anaphylaxis. Esthetics establishment staff should always ask about latex allergy during the client intake and have non-latex gloves (nitrile or vinyl) available. Airborne latex particles from powdered gloves can also trigger reactions in sensitized individuals." },
  { id: 112, question: "The difference between bactericidal and bacteriostatic agents is:", question_es: "La diferencia entre agentes bactericidas y bacteriostáticos es:", options: ["Bactericidal agents kill bacteria; bacteriostatic agents inhibit bacterial growth and reproduction without killing them — most disinfectants required for esthetics are bactericidal", "Bactericidal agents inhibit growth; bacteriostatic agents kill bacteria — the terms are often confused", "Both terms mean the same thing — killing bacteria by different mechanisms", "Bacteriostatic agents are preferred for esthetics implement disinfection because they are gentler on surfaces"], options_es: ["Los agentes bactericidas matan las bacterias; los agentes bacteriostáticos inhiben el crecimiento y la reproducción bacteriana sin matarlos — la mayoría de los desinfectantes requeridos para la estética son bactericidas", "Los agentes bactericidas inhiben el crecimiento; los agentes bacteriostáticos matan las bacterias — los términos a menudo se confunden", "Ambos términos significan lo mismo — matar bacterias por diferentes mecanismos", "Los agentes bacteriostáticos son preferidos para la desinfección de implementos de estética porque son más suaves con las superficies"], correct: 0, explanation: "Bactericidal = kills bacteria (irreversible). Bacteriostatic = inhibits growth (if removed, bacteria may resume growing). Disinfectants for implement sanitation must be bactericidal — they must kill pathogens, not merely suppress growth. This distinction is important when selecting appropriate products for esthetics disinfection." },
  { id: 113, question: "An esthetician should avoid contaminating professional product jars by:", question_es: "Un esteticista debe evitar contaminar los tarros de productos profesionales mediante:", options: ["Always using a clean, sanitized spatula or pump dispenser to remove product — never inserting fingers directly into the jar, as finger contact introduces bacteria and contaminates the entire product", "Wearing gloves when dipping fingers into product jars — gloves make direct finger contact acceptable", "Only using products that come in jars with wide openings — narrow openings prevent proper cleaning", "Replacing product jars completely after every client service"], options_es: ["Siempre usar una espátula limpia y saneada o un dispensador de bomba para sacar el producto — nunca insertar los dedos directamente en el tarro, ya que el contacto con los dedos introduce bacterias y contamina todo el producto", "Usar guantes al meter los dedos en los tarros de producto — los guantes hacen que el contacto directo con los dedos sea aceptable", "Solo usar productos que vienen en tarros con aberturas amplias — las aperturas estrechas evitan la limpieza adecuada", "Reemplazar los tarros de producto completamente después de cada servicio al cliente"], correct: 0, explanation: "Inserting fingers (even gloved fingers) directly into multi-use product jars introduces bacteria that can survive and multiply in the product, potentially causing client infections when applied to skin. Spatulas and pump dispensers maintain product hygiene. Once contaminated, products may develop visible mold or bacterial colonies." },
  { id: 114, question: "The correct disposal method for contaminated cotton pads, gauze, and other blood-contaminated waste in an esthetics establishment is:", question_es: "El método de eliminación correcto para almohadillas de algodón contaminadas, gasa y otros residuos contaminados con sangre en un establecimiento de estética es:", options: ["Place in a sealed plastic bag or biohazard-labeled container and dispose of according to local regulations for regulated medical waste — blood-saturated materials may require biohazard disposal in some jurisdictions", "Place in the regular trash bin alongside other waste materials — no special disposal is required for small amounts of blood", "Flush down the toilet — biological waste is best disposed of in the sewage system", "Return blood-contaminated items to the product manufacturer for proper disposal"], options_es: ["Colocar en una bolsa de plástico sellada o un contenedor etiquetado como biohazard y desechar según las regulaciones locales para residuos médicos regulados — los materiales saturados de sangre pueden requerir eliminación de biohazard en algunas jurisdicciones", "Colocar en el basurero regular junto con otros materiales de desecho — no se requiere eliminación especial para pequeñas cantidades de sangre", "Tirar por el inodoro — los residuos biológicos se eliminan mejor en el sistema de alcantarillado", "Devolver los artículos contaminados con sangre al fabricante del producto para su eliminación adecuada"], correct: 0, explanation: "Blood-contaminated materials (cotton, gauze, extraction tissues) may be considered regulated medical waste depending on the quantity and local regulations. Best practice: place in a sealed bag, separate from general waste, and dispose of per local/state requirements. Sharps (lancets, needles) always go in approved sharps containers — never regular trash." },
  { id: 115, question: "Airborne transmission of pathogens during esthetics services is a concern because:", question_es: "La transmisión aérea de patógenos durante los servicios de estética es una preocupación porque:", options: ["Esthetics services involve close face-to-face contact — respiratory droplets and, for some pathogens, airborne particles can be exchanged between the esthetician and client during facial services performed at close range", "Airborne pathogens cannot survive in the climate-controlled environment of an esthetics establishment", "Only outdoor esthetics services present airborne transmission risk", "Airborne transmission is only relevant for respiratory procedures — esthetics services involve no breathing by the esthetician or client"], options_es: ["Los servicios de estética implican contacto cara a cara cercano — las gotitas respiratorias y, para algunos patógenos, las partículas en el aire pueden intercambiarse entre el esteticista y el cliente durante los servicios faciales realizados a corta distancia", "Los patógenos aéreos no pueden sobrevivir en el entorno con clima controlado de un establecimiento de estética", "Solo los servicios de estética al aire libre presentan riesgo de transmisión aérea", "La transmisión aérea solo es relevante para procedimientos respiratorios — los servicios de estética no implican respiración del esteticista o del cliente"], correct: 0, explanation: "Facial esthetics services are performed in extremely close proximity to the client's face, creating potential for both droplet and airborne pathogen exposure. Wearing masks during facial services (especially when the client has a respiratory illness or during high-risk periods) reduces exposure for the esthetician and client alike." },
  { id: 116, question: "Comedone extractors and lancets used in extractions must be disinfected/sterilized because:", question_es: "Los extractores de comedones y lancetas usadas en extracciones deben desinfectarse/esterilizarse porque:", options: ["They contact non-intact skin and potentially blood during extractions — lantcets that pierce skin must be sterile and single-use; metal extractors that contact compromised skin require high-level disinfection after each use", "These implements only contact the skin surface and require only basic cleaning with soap and water", "Extractors are classified as non-critical implements that require only low-level sanitization", "Extraction implements are single-use by definition and do not require disinfection"], options_es: ["Entran en contacto con piel no intacta y potencialmente sangre durante las extracciones — las lancetas que perforan la piel deben ser estériles y de uso único; los extractores de metal que contactan piel comprometida requieren desinfección de alto nivel después de cada uso", "Estos implementos solo contactan la superficie de la piel y requieren solo limpieza básica con jabón y agua", "Los extractores se clasifican como implementos no críticos que requieren solo saneamiento de bajo nivel", "Los implementos de extracción son de uso único por definición y no requieren desinfección"], correct: 0, explanation: "Extractions break the skin's surface, creating potential for blood contact and infection introduction. Lancets must be sterile single-use (needle, not reusable). Metal comedone extractors contact compromised skin and must receive high-level disinfection after each use. Failure to properly decontaminate extraction tools is a significant infection transmission risk." },
  { id: 117, question: "Steam used in facial esthetics services (from a facial steamer) should be managed by:", question_es: "El vapor utilizado en los servicios faciales de estética (de una vaporizadora facial) debe manejarse:", options: ["Using only distilled water in the steamer to prevent mineral buildup, regularly cleaning and disinfecting the steamer unit, and never directing steam directly onto broken skin, active lesions, or highly sensitized skin", "Using tap water — mineral content in tap water enhances the steam's therapeutic benefits", "Directing steam intensely onto comedones to force them open before extractions", "Leaving the steamer running between clients to maintain constant steam temperature in the room"], options_es: ["Usando solo agua destilada en la vaporizadora para prevenir la acumulación de minerales, limpiando y desinfectando regularmente la unidad vaporizadora y nunca dirigiendo el vapor directamente sobre piel rota, lesiones activas o piel muy sensibilizada", "Usando agua del grifo — el contenido mineral del agua del grifo mejora los beneficios terapéuticos del vapor", "Dirigiendo el vapor intensamente sobre los comedones para forzarlos a abrirse antes de las extracciones", "Dejando la vaporizadora funcionando entre clientes para mantener una temperatura de vapor constante en la sala"], correct: 0, explanation: "Distilled water prevents mineral scale buildup in the steamer that can harbor bacteria and reduce steamer effectiveness. Steamers should be cleaned per manufacturer guidelines. Direct intense steam on broken skin, active acne pustules, or rosacea is a contraindication — heat can worsen inflammation and spread infection." },
  { id: 118, question: "The proper procedure for disposing of a used single-use wax applicator (wooden spatula) is:", question_es: "El procedimiento correcto para desechar un aplicador de cera de uso único usado (espátula de madera) es:", options: ["Discard it in the waste bin immediately after single use — it cannot be reused on the same client or a different client and cannot be disinfected because wood is a porous material", "Soak in disinfectant for 10 minutes and reuse on the next client", "Rinse with hot water and use again for the rest of the current client's service", "Return the used applicator to the wax pot if no new wax has been added since it was used"], options_es: ["Desecharlo en el basurero inmediatamente después de un solo uso — no se puede reutilizar en el mismo cliente o en un cliente diferente y no se puede desinfectar porque la madera es un material poroso", "Remojar en desinfectante durante 10 minutos y reutilizar en el próximo cliente", "Enjuagar con agua caliente y usar nuevamente para el resto del servicio del cliente actual", "Devolver el aplicador usado al pote de cera si no se ha añadido nueva cera desde que se usó"], correct: 0, explanation: "Wooden wax applicators (spatulas) are porous and cannot be adequately disinfected — they must be discarded after a single use. Once an applicator touches a client's skin, it must not be reintroduced into the wax pot (no double-dipping) and must be thrown away. Reusing wooden applicators is a serious sanitation violation." },
  { id: 119, question: "When disinfecting non-porous implements (metal tweezers, stainless steel extractors) in quaternary ammonium solution:", question_es: "Al desinfectar implementos no porosos (pinzas de metal, extractores de acero inoxidable) en solución de amonio cuaternario:", options: ["The implement must first be cleaned (debris removed with soap and water), rinsed, and then fully submerged in the freshly prepared disinfectant solution for the full contact time specified on the label — typically 10 minutes", "Simply spray the disinfectant on the implement surface and wipe dry immediately", "Soak for 30 seconds — extended contact time is unnecessary for metal implements", "Allow the implement to air dry in the disinfectant — removing it from solution is not required"], options_es: ["El implemento primero debe limpiarse (eliminación de residuos con jabón y agua), enjuagarse y luego sumergirse completamente en la solución desinfectante recién preparada durante el tiempo de contacto completo especificado en la etiqueta — típicamente 10 minutos", "Simplemente rocíe el desinfectante en la superficie del implemento y séquelo de inmediato", "Remojar durante 30 segundos — el tiempo de contacto prolongado no es necesario para los implementos de metal", "Deje que el implemento se seque al aire en el desinfectante — no es necesario retirarlo de la solución"], correct: 0, explanation: "Correct disinfection sequence: (1) clean with soap and water to remove all debris, (2) rinse, (3) submerge in freshly prepared EPA-registered disinfectant for the full label-specified contact time (typically 10 minutes for quats), (4) remove, rinse (if indicated), dry, and store in a clean covered container. Shortcuts defeat the process." },
  { id: 120, question: "The concept of 'cross-contamination' in esthetics refers to:", question_es: "El concepto de 'contaminación cruzada' en estética se refiere a:", options: ["The transfer of pathogens from one person, surface, or implement to another — for example, from one client's skin to an implement, and then from that implement to the next client's skin if not properly disinfected", "Mixing different product brands, which can cause chemical reactions", "Applying products intended for the face to the body, or vice versa", "The mixing of clean and used towels in the same storage area"], options_es: ["La transferencia de patógenos de una persona, superficie o implemento a otro — por ejemplo, de la piel de un cliente a un implemento, y luego de ese implemento a la piel del próximo cliente si no se desinfecta adecuadamente", "Mezclar diferentes marcas de productos, lo que puede causar reacciones químicas", "Aplicar productos destinados al rostro al cuerpo, o viceversa", "La mezcla de toallas limpias y usadas en la misma área de almacenamiento"], correct: 0, explanation: "Cross-contamination is the primary infection control concern in esthetics. Every surface, implement, and product that contacts one client can theoretically transfer pathogens to the next client if not properly decontaminated. All sanitation protocols (cleaning, disinfecting, single-use items, fresh linens) are designed to prevent cross-contamination." },
  { id: 121, question: "Disposable (single-use) facial sponges, applicator brushes, and cotton rounds should be used in esthetics because:", question_es: "Las esponjas faciales desechables (de uso único), los pinceles aplicadores y las almohadillas de algodón deben usarse en la estética porque:", options: ["Porous materials (sponge, cotton, natural bristles) cannot be reliably disinfected — they absorb fluids and harbor bacteria in their porous structure; single-use items eliminate the cross-contamination risk entirely", "Disposable items are required by TDLR for all esthetics services without exception", "Disposable items provide a higher quality service experience compared to reusable items", "Reusable sponges can be safely sterilized in an autoclave, making disposable items unnecessary"], options_es: ["Los materiales porosos (esponja, algodón, cerdas naturales) no pueden desinfectarse de manera confiable — absorben fluidos y albergan bacterias en su estructura porosa; los artículos de uso único eliminan por completo el riesgo de contaminación cruzada", "Los artículos desechables son requeridos por TDLR para todos los servicios de estética sin excepción", "Los artículos desechables proporcionan una experiencia de servicio de mayor calidad en comparación con los artículos reutilizables", "Las esponjas reutilizables pueden esterilizarse de forma segura en un autoclave, haciendo que los artículos desechables sean innecesarios"], correct: 0, explanation: "Porous materials cannot withstand the disinfection processes needed for esthetics implements — their pores trap organic material and protect bacteria from disinfectants. Single-use sponges, cotton rounds, and disposable applicators eliminate cross-contamination between clients. Sponges cannot be autoclaved effectively." },
  { id: 122, question: "In an esthetics establishment, which surfaces require routine disinfection between clients?", question_es: "En un establecimiento de estética, ¿qué superficies requieren desinfección de rutina entre clientes?", options: ["Any surface the client or the esthetician's hands may have contacted — including the facial bed/chair (head, back, armrests), service cart top, tool tray, light switches, and doorknobs", "Only the facial bed — other surfaces do not require disinfection between clients", "Surfaces only need disinfection at the end of the workday", "Only surfaces in the reception area — the treatment room self-disinfects between clients from UV exposure"], options_es: ["Cualquier superficie que el cliente o las manos del esteticista puedan haber contactado — incluyendo la cama/silla facial (cabeza, respaldo, reposabrazos), la parte superior del carrito de servicio, la bandeja de herramientas, los interruptores de luz y los pomos de las puertas", "Solo la cama facial — otras superficies no requieren desinfección entre clientes", "Las superficies solo necesitan desinfección al final del día de trabajo", "Solo las superficies en el área de recepción — la sala de tratamiento se auto-desinfecta entre clientes por exposición UV"], correct: 0, explanation: "All surfaces that were contacted by the client or the esthetician's hands during the service are potentially contaminated and must be disinfected between clients. This includes the facial bed, headrest, service cart, tool tray, and high-touch surfaces. A consistent room-turnover protocol ensures all surfaces are properly disinfected." },
  { id: 123, question: "The shelf life of a properly prepared disinfectant solution in an esthetics establishment is:", question_es: "La vida útil de una solución desinfectante correctamente preparada en un establecimiento de estética es:", options: ["As specified by the manufacturer on the product label — most solutions (like quats) must be changed at least daily or more frequently if visibly soiled, because organic matter accumulates and reduces efficacy over time", "Indefinite — a properly prepared disinfectant remains effective until it is visibly dirty", "Always exactly 24 hours regardless of the product or conditions", "30 days — most professional disinfectants remain effective for one month after preparation"], options_es: ["Como lo especifica el fabricante en la etiqueta del producto — la mayoría de las soluciones (como los cuats) deben cambiarse al menos diariamente o con mayor frecuencia si están visiblemente sucias, porque la materia orgánica se acumula y reduce la eficacia con el tiempo", "Indefinida — un desinfectante correctamente preparado sigue siendo efectivo hasta que esté visiblemente sucio", "Siempre exactamente 24 horas independientemente del producto o las condiciones", "30 días — la mayoría de los desinfectantes profesionales siguen siendo efectivos durante un mes después de su preparación"], correct: 0, explanation: "Disinfectant solutions have limited shelf life after preparation. Organic matter from implements accumulates and inactivates the solution. Manufacturer guidelines dictate change frequency — many require daily changes. Always prepare fresh solution and follow label instructions. Never top off old solution with new solution." },
  { id: 124, question: "An esthetician who develops a cut or open wound on their hand during a service should:", question_es: "Un esteticista que desarrolla un corte o herida abierta en la mano durante un servicio debe:", options: ["Stop the service, clean and bandage the wound, cover with a glove or finger cot to protect both the wound and the client, then continue with appropriate PPE in place — an uncovered open wound is a bilateral infection risk", "Continue the service without stopping — minor cuts do not require any immediate action during service", "Stop the service and refer the client to a different esthetician — the service cannot continue under any circumstances", "Apply antiseptic cream and continue — topical antiseptic provides sufficient protection without gloves"], options_es: ["Detener el servicio, limpiar y vender la herida, cubrir con un guante o un dedal de dedo para proteger tanto la herida como al cliente, luego continuar con el EPP adecuado en su lugar — una herida abierta sin cubrir es un riesgo de infección bilateral", "Continuar el servicio sin detenerse — los cortes menores no requieren ninguna acción inmediata durante el servicio", "Detener el servicio y referir al cliente a otro esteticista — el servicio no puede continuar bajo ninguna circunstancia", "Aplicar crema antiséptica y continuar — el antiséptico tópico proporciona protección suficiente sin guantes"], correct: 0, explanation: "An open wound on the esthetician's hand is a bilateral risk — the esthetician's wound can expose them to client pathogens, and vice versa. The correct response: clean and bandage the wound, then cover with a glove or finger cot to maintain the barrier. Service may continue with the wound properly protected." },
  { id: 125, question: "Spores (bacterial endospores) are significant in infection control because:", question_es: "Las esporas (endosporas bacterianas) son significativas en el control de infecciones porque:", options: ["Bacterial endospores are extremely resistant to heat, drying, and many chemical disinfectants — only sterilization (autoclaving or equivalent) reliably destroys spores; this is why sterilization is required for skin-piercing implements", "Spores are the same as regular bacteria and are killed by standard disinfectants at normal concentrations", "Spores only form in outdoor environments and are not relevant to the controlled indoor environment of esthetics establishments", "Spores from Bacillus anthracis are the only relevant spore-forming organism in esthetics — all other spores are harmless"], options_es: ["Las endosporas bacterianas son extremadamente resistentes al calor, el secado y muchos desinfectantes químicos — solo la esterilización (autoclave o equivalente) destruye de manera confiable las esporas; por eso se requiere esterilización para los implementos que perforan la piel", "Las esporas son iguales a las bacterias regulares y son eliminadas por desinfectantes estándar a concentraciones normales", "Las esporas solo se forman en entornos exteriores y no son relevantes para el entorno interior controlado de los establecimientos de estética", "Las esporas de Bacillus anthracis son el único organismo formador de esporas relevante en la estética — todas las demás esporas son inofensivas"], correct: 0, explanation: "Endospores (produced by Bacillus and Clostridium species) are dormant bacterial forms highly resistant to heat, drying, UV, and most disinfectants. Autoclave sterilization (moist heat at 121°C) is the standard for destroying spores. This is why skin-piercing implements must be sterilized rather than merely disinfected." },
  { id: 126, question: "Distilled water is preferred over tap water when preparing some disinfectant solutions because:", question_es: "El agua destilada es preferida sobre el agua del grifo al preparar algunas soluciones desinfectantes porque:", options: ["Minerals (calcium, magnesium) in hard tap water can react with some disinfectants (especially quaternary ammonium compounds) and reduce their effectiveness — distilled water prevents this mineral interference", "Tap water contains added chlorine that destroys all disinfectant compounds on contact", "Distilled water has a lower pH that activates disinfectant compounds more effectively", "There is no practical difference — tap water and distilled water produce equivalent disinfectant solutions"], options_es: ["Los minerales (calcio, magnesio) en el agua dura del grifo pueden reaccionar con algunos desinfectantes (especialmente los compuestos de amonio cuaternario) y reducir su efectividad — el agua destilada evita esta interferencia mineral", "El agua del grifo contiene cloro añadido que destruye todos los compuestos desinfectantes al contacto", "El agua destilada tiene un pH más bajo que activa los compuestos desinfectantes de manera más efectiva", "No hay diferencia práctica — el agua del grifo y el agua destilada producen soluciones desinfectantes equivalentes"], correct: 0, explanation: "Hard water minerals (especially calcium and magnesium) can react with quaternary ammonium disinfectants, reducing their efficacy. This is called 'water hardness interference.' Manufacturers may specify using distilled or soft water for their products. Always check the product label for water requirements." },
  { id: 127, question: "'High-level disinfection' as it applies to esthetics implements means:", question_es: "La 'desinfección de alto nivel' tal como aplica a los implementos de estética significa:", options: ["Killing all vegetative microorganisms and most (but not all) bacterial endospores using EPA-registered high-level disinfectants or FDA-approved chemical sterilants at appropriate concentrations and contact times — required for semi-critical items", "Simply cleaning implements with soap and water before reuse", "Using any EPA-registered disinfectant at any concentration for any length of time", "Applying 70% isopropyl alcohol and allowing the implement to air dry"], options_es: ["Matar todos los microorganismos vegetativos y la mayoría (pero no todas) las endosporas bacterianas usando desinfectantes de alto nivel registrados por la EPA o esterilizantes químicos aprobados por la FDA a concentraciones y tiempos de contacto apropiados — requerido para artículos semi-críticos", "Simplemente limpiar los implementos con jabón y agua antes de reutilizarlos", "Usar cualquier desinfectante registrado por la EPA a cualquier concentración durante cualquier período de tiempo", "Aplicar alcohol isopropílico al 70% y permitir que el implemento se seque al aire"], correct: 0, explanation: "High-level disinfection (HLD) kills all vegetative bacteria, mycobacteria, fungi, and viruses, and most spores. It is achieved with specific EPA-registered/FDA-cleared high-level disinfectants (like glutaraldehyde, OPA, or hydrogen peroxide at appropriate concentrations) for specified contact times. HLD is required for semi-critical implements in healthcare." },
  { id: 128, question: "A 10% bleach solution (sodium hypochlorite) used in an esthetics establishment for disinfection must be:", question_es: "Una solución de lejía al 10% (hipoclorito de sodio) utilizada en un establecimiento de estética para la desinfección debe ser:", options: ["Freshly prepared each day of use (bleach solutions degrade rapidly and lose efficacy), used at the correct concentration, and kept away from metal implements (bleach corrodes metals over time)", "Prepared weekly in large batches and stored at room temperature for ongoing use", "Mixed at 50% bleach to 50% water for effective disinfection of facial implements", "Used on all metal implements as the primary disinfectant because bleach kills all pathogens"], options_es: ["Preparada fresca cada día de uso (las soluciones de lejía se degradan rápidamente y pierden eficacia), usada a la concentración correcta y mantenida alejada de los implementos de metal (la lejía corroe los metales con el tiempo)", "Preparada semanalmente en grandes cantidades y almacenada a temperatura ambiente para uso continuo", "Mezclada al 50% de lejía con 50% de agua para la desinfección efectiva de implementos faciales", "Usada en todos los implementos de metal como el desinfectante principal porque la lejía mata todos los patógenos"], correct: 0, explanation: "Bleach (sodium hypochlorite) solutions degrade rapidly — they should be prepared fresh daily and stored in opaque, covered containers away from light and heat. Bleach at 1:10 dilution (approximately 0.5% sodium hypochlorite) is effective for surface disinfection but damages metal implements and certain materials over time." },
  { id: 129, question: "Product contamination from client 'back-contamination' occurs when:", question_es: "La contaminación del producto por 'retrocontaminación' del cliente ocurre cuando:", options: ["An applicator used on the client's skin is returned to the product container — skin cells, bacteria, and sebum from the client contaminate the product, which can then infect subsequent clients when applied", "A client touches the outside of a sealed product bottle", "A product is stored near a window and exposed to UV light from the sun", "Two different product brands are mixed in the same jar"], options_es: ["Un aplicador usado en la piel del cliente se devuelve al recipiente del producto — las células de la piel, las bacterias y el sebo del cliente contaminan el producto, que luego puede infectar a clientes posteriores cuando se aplica", "Un cliente toca el exterior de una botella de producto sellado", "Un producto se almacena cerca de una ventana y se expone a la luz UV del sol", "Dos marcas de productos diferentes se mezclan en el mismo tarro"], correct: 0, explanation: "Back-contamination (also called 'back-bar contamination') occurs when a used applicator is returned to the product container. To prevent it: always use clean spatulas to dispense product onto a clean mixing plate or gauze, and never double-dip. This applies to creams, masks, gels, and all multi-use product containers." },
  { id: 130, question: "Folliculitis is a skin condition relevant to esthetics because:", question_es: "La foliculitis es una condición cutánea relevante para la estética porque:", options: ["Folliculitis (bacterial or fungal infection of the hair follicle, causing red papules or pustules around follicles) can be worsened by esthetics services — it may be contraindicated in the affected area and should be referred to a physician if suspected", "Folliculitis is a normal skin condition that every client has to some degree and requires no service modification", "Folliculitis is a cosmetic concern only and is completely safe to treat with extractions", "Folliculitis is caused by esthetics products and the esthetician is always legally responsible for its development"], options_es: ["La foliculitis (infección bacteriana o fúngica del folículo piloso, que causa pápulas o pústulas rojas alrededor de los folículos) puede empeorar con los servicios de estética — puede estar contraindicada en el área afectada y debe derivarse a un médico si se sospecha", "La foliculitis es una condición cutánea normal que todos los clientes tienen en algún grado y no requiere modificación del servicio", "La foliculitis es solo una preocupación cosmética y es completamente seguro tratarla con extracciones", "La foliculitis es causada por los productos de estética y el esteticista siempre es legalmente responsable de su desarrollo"], correct: 0, explanation: "Folliculitis presents as inflamed red papules or pustules at follicle openings. Causes include bacteria (usually Staph aureus), fungi, or irritation. Facial esthetics services — especially steam, extractions, or waxing — in areas with active folliculitis can spread the infection. Referral to a physician is appropriate for suspected folliculitis." },
  { id: 131, question: "Impetigo is relevant to esthetics because:", question_es: "El impétigo es relevante para la estética porque:", options: ["Impetigo is a highly contagious bacterial skin infection (usually Staphylococcus or Streptococcus) that presents as honey-crusted lesions — active impetigo on the face is a contraindication for all facial services and requires physician treatment", "Impetigo is a non-contagious hereditary skin condition with no bearing on esthetics services", "Impetigo is easily treated with any over-the-counter antiseptic cream during the esthetics facial", "Impetigo only affects children — adult clients never present with this condition"], options_es: ["El impétigo es una infección cutánea bacteriana altamente contagiosa (generalmente Staphylococcus o Streptococcus) que se presenta como lesiones con costras amarillas — el impétigo activo en el rostro es una contraindicación para todos los servicios faciales y requiere tratamiento médico", "El impétigo es una condición cutánea hereditaria no contagiosa sin relación con los servicios de estética", "El impétigo se trata fácilmente con cualquier crema antiséptica de venta libre durante el facial de estética", "El impétigo solo afecta a los niños — los clientes adultos nunca presentan esta condición"], correct: 0, explanation: "Impetigo is a contagious superficial bacterial skin infection. Its characteristic honey-colored crusts are highly infectious — direct contact or shared implements can spread the infection. Active impetigo anywhere on or near the face or service area is a firm contraindication. The client should be referred to a physician for antibiotic treatment." },
  { id: 132, question: "Warts (verrucae) caused by Human Papillomavirus (HPV) are a concern in esthetics because:", question_es: "Las verrugas (verrugas vulgares) causadas por el Virus del Papiloma Humano (VPH) son una preocupación en la estética porque:", options: ["HPV is contagious — warts can spread through direct skin contact or contact with contaminated implements; waxing, extractions, or microneedling over or near warts can spread the virus and the warts themselves", "Warts are non-infectious benign growths — no transmission risk exists in an esthetics setting", "HPV is only transmitted sexually and has no relevance to esthetic services on the face or body", "Standard EPA-registered disinfectants eliminate all HPV risk — no special precautions are needed beyond routine disinfection"], options_es: ["El VPH es contagioso — las verrugas pueden diseminarse a través del contacto directo con la piel o el contacto con implementos contaminados; el encerado, las extracciones o la microagujas sobre o cerca de las verrugas pueden diseminar el virus y las verrugas mismas", "Las verrugas son crecimientos benignos no infecciosos — no existe ningún riesgo de transmisión en un entorno de estética", "El VPH solo se transmite sexualmente y no tiene relevancia para los servicios estéticos en el rostro o el cuerpo", "Los desinfectantes estándar registrados por la EPA eliminan todo riesgo de VPH — no se necesitan precauciones especiales más allá de la desinfección de rutina"], correct: 0, explanation: "Warts are caused by HPV and are contagious. Trauma to wart tissue (from waxing, microneedling, or aggressive manipulation) can spread HPV to surrounding skin. Implements that contact wart tissue must be properly disinfected. Estheticians should avoid servicing areas with active warts and refer clients to a dermatologist for wart treatment." },
  { id: 133, question: "The sanitizing and disinfection protocols in a Texas esthetics establishment protect against which TDLR-regulated outcomes?", question_es: "Los protocolos de saneamiento y desinfección en un establecimiento de estética de Texas protegen contra cuáles resultados regulados por TDLR?", options: ["Transmission of contagious conditions between clients, infection introduction through skin compromise during services, and sanitation violations that would result in TDLR fines or establishment closure", "Only cosmetic outcomes — sanitation has no regulatory purpose beyond aesthetic cleanliness", "Only protecting the esthetician from occupational infection — client protection is the client's own responsibility", "Financial losses from product waste — sanitation protocols primarily protect the establishment's investment in products"], options_es: ["Transmisión de condiciones contagiosas entre clientes, introducción de infecciones a través del compromiso de la piel durante los servicios y violaciones de saneamiento que resultarían en multas de TDLR o cierre del establecimiento", "Solo resultados cosméticos — el saneamiento no tiene ningún propósito regulatorio más allá de la limpieza estética", "Solo proteger al esteticista de la infección ocupacional — la protección del cliente es responsabilidad del propio cliente", "Pérdidas financieras por desperdicio de productos — los protocolos de saneamiento protegen principalmente la inversión del establecimiento en productos"], correct: 0, explanation: "TDLR sanitation regulations exist to protect public health. Proper sanitation prevents: (1) transmission of infections between clients via contaminated implements and surfaces, (2) infection of compromised skin during extractions and other invasive services, and (3) TDLR enforcement action for sanitation violations found during inspections." },
  { id: 134, question: "After each client, an esthetician should perform which of the following room turnover tasks before the next client enters?", question_es: "Después de cada cliente, un esteticista debe realizar cuáles de las siguientes tareas de preparación de la sala antes de que entre el próximo cliente?", options: ["Remove and place used linens in the soiled linen container; discard all single-use items; place used implements in the dirty implement container; disinfect surfaces (bed, cart, tray); set out fresh linens; prepare clean disinfected implements for the next service", "Simply fluff the pillow and straighten the room — detailed room turnover is only needed at the end of the day", "Only replace the paper drape on the facial bed — all other items may remain from the previous client", "Wipe surfaces with a dry cloth and replace only visibly soiled items"], options_es: ["Retirar y colocar la ropa de cama usada en el contenedor de ropa sucia; desechar todos los artículos de uso único; colocar los implementos usados en el contenedor de implementos sucios; desinfectar las superficies (cama, carrito, bandeja); poner ropa de cama fresca; preparar implementos desinfectados limpios para el próximo servicio", "Simplemente esponjar la almohada y ordenar la sala — la preparación detallada de la sala solo es necesaria al final del día", "Solo reemplazar el paño de papel en la cama facial — todos los demás artículos pueden permanecer del cliente anterior", "Limpiar las superficies con un paño seco y reemplazar solo los artículos visiblemente sucios"], correct: 0, explanation: "A complete room turnover between clients includes: removing all used linens (to soiled linen bin), discarding single-use items, placing used implements in the contaminated container, disinfecting all contact surfaces with EPA-registered disinfectant (full contact time), laying fresh linens, and preparing clean disinfected implements. This protects each client." },
  { id: 135, question: "A client with a known allergy to certain disinfectant ingredients (such as quaternary ammonium compounds) requires the esthetician to:", question_es: "Un cliente con alergia conocida a ciertos ingredientes desinfectantes (como los compuestos de amonio cuaternario) requiere que el esteticista:", options: ["Ensure implements and surfaces are fully dry before client contact (residual traces of the disinfectant can cause reactions), and consider using an alternative disinfectant if the allergy is severe — after thorough rinsing of implements post-disinfection", "Avoid all disinfection to prevent the client's allergic reaction during the service", "Ask the client to take an antihistamine before the service and proceed as normal", "Use distilled water as the disinfectant for all implements used on that client"], options_es: ["Asegurarse de que los implementos y superficies estén completamente secos antes del contacto con el cliente (los rastros residuales del desinfectante pueden causar reacciones) y considerar usar un desinfectante alternativo si la alergia es severa — después de un enjuague minucioso de los implementos post-desinfección", "Evitar toda desinfección para prevenir la reacción alérgica del cliente durante el servicio", "Pedirle al cliente que tome un antihistamínico antes del servicio y proceder con normalidad", "Usar agua destilada como desinfectante para todos los implementos usados en ese cliente"], correct: 0, explanation: "If a client is allergic to residual disinfectant, thoroughly rinse implements after disinfection to remove traces. Ensure surfaces are completely dry. Skipping disinfection is never acceptable — proper disinfection must occur, followed by appropriate rinsing and drying to remove residues before client contact." },
  { id: 136, question: "Which of the following correctly describes the difference between cleaning, disinfecting, and sanitizing in an esthetics context?", question_es: "¿Cuál de los siguientes describe correctamente la diferencia entre limpiar, desinfectar y sanear en el contexto de la estética?", options: ["Cleaning physically removes dirt and debris (necessary first step); sanitizing reduces microbial count to a safe level (lower standard than disinfection); disinfecting kills most pathogens on non-living surfaces using EPA-registered products (required for implements)", "All three terms mean the same thing in esthetics — they are interchangeable", "Sanitizing kills all pathogens; disinfecting reduces microbial counts; cleaning sterilizes", "Cleaning requires EPA-registered products; disinfecting only requires soap and water"], options_es: ["Limpiar elimina físicamente la suciedad y los residuos (primer paso necesario); sanear reduce el recuento microbiano a un nivel seguro (estándar más bajo que la desinfección); desinfectar mata la mayoría de los patógenos en superficies no vivas usando productos registrados por la EPA (requerido para implementos)", "Los tres términos significan lo mismo en estética — son intercambiables", "Sanear mata todos los patógenos; desinfectar reduce los recuentos microbianos; limpiar esteriliza", "Limpiar requiere productos registrados por la EPA; desinfectar solo requiere jabón y agua"], correct: 0, explanation: "The three distinct processes: Cleaning = physical removal of debris (soap/water/mechanical action — always first). Sanitizing = reducing microbial count to safe levels (used for food-contact surfaces; hand washing is a form of sanitation). Disinfecting = killing most pathogens on non-living surfaces with EPA-registered chemical products (required for esthetics implements)." },
  { id: 137, question: "Proper storage of clean, disinfected towels and linens in an esthetics establishment requires:", question_es: "El almacenamiento adecuado de toallas y ropa de cama limpias y desinfectadas en un establecimiento de estética requiere:", options: ["Storing in a clean, covered cabinet or drawer separate from soiled linens — clean linens must be protected from contamination until use", "Storing in the same area as soiled linens since both will be laundered eventually", "Hanging on open hooks in the service room where air circulates freely around them", "Folding and placing on the service cart immediately after laundering without covering"], options_es: ["Almacenar en un gabinete o cajón limpio y cubierto separado de la ropa de cama sucia — la ropa de cama limpia debe protegerse de la contaminación hasta su uso", "Almacenar en la misma área que la ropa de cama sucia ya que ambas se lavarán eventualmente", "Colgar en ganchos abiertos en la sala de servicio donde el aire circula libremente alrededor", "Doblar y colocar en el carrito de servicio inmediatamente después del lavado sin cubrir"], correct: 0, explanation: "Clean and soiled linens must be stored separately in all circumstances. Clean linens go in a covered, designated clean storage area; soiled linens go in a covered, separate dirty linen container. Storing them together defeats the purpose of laundering and risks recontaminating clean items." },
  { id: 138, question: "The concept of 'engineering controls' in OSHA's Bloodborne Pathogen Standard relevant to esthetics includes:", question_es: "El concepto de 'controles de ingeniería' en el Estándar de Patógenos de Transmisión Sanguínea de OSHA relevante para la estética incluye:", options: ["Physical devices that isolate or remove bloodborne pathogen hazards — such as puncture-resistant sharps containers, self-sheathing needles, and safety lancets that reduce the risk of needlestick injury during esthetics services", "Air conditioning systems that reduce the concentration of airborne pathogens", "Chemical disinfectants applied to surfaces to prevent pathogen growth", "Client screening forms that identify bloodborne pathogen status before service"], options_es: ["Dispositivos físicos que aíslan o eliminan los peligros de patógenos de transmisión sanguínea — como contenedores de objetos cortantes resistentes a pinchazos, agujas auto-protegidas y lancetas de seguridad que reducen el riesgo de lesión por pinchazo durante los servicios de estética", "Sistemas de aire acondicionado que reducen la concentración de patógenos en el aire", "Desinfectantes químicos aplicados a superficies para prevenir el crecimiento de patógenos", "Formularios de evaluación de clientes que identifican el estado de patógenos de transmisión sanguínea antes del servicio"], correct: 0, explanation: "Engineering controls are physical safeguards that reduce exposure risk. In esthetics: puncture-resistant sharps containers (prevent needlestick when discarding lancets), safety lancets with retractable needles, and other devices that prevent blood exposure. Engineering controls work independently of worker behavior — they provide protection even if work practices are imperfect." },
  { id: 139, question: "Sanitation in an esthetics establishment differs from infection control in a hospital because:", question_es: "El saneamiento en un establecimiento de estética difiere del control de infecciones en un hospital porque:", options: ["Esthetics establishments primarily use disinfection (not sterilization) for most implements — only skin-piercing implements require sterilization; hospitals require sterilization for all implements that contact internal tissues or blood", "Esthetics establishments have stricter sanitation requirements than hospitals", "There is no difference — esthetics and hospital infection control protocols are identical", "Hospitals do not need to disinfect implements between patients — they use only single-use disposables for everything"], options_es: ["Los establecimientos de estética usan principalmente desinfección (no esterilización) para la mayoría de los implementos — solo los implementos que perforan la piel requieren esterilización; los hospitales requieren esterilización para todos los implementos que contactan tejidos internos o sangre", "Los establecimientos de estética tienen requisitos de saneamiento más estrictos que los hospitales", "No hay diferencia — los protocolos de control de infecciones de estética y hospital son idénticos", "Los hospitales no necesitan desinfectar los implementos entre pacientes — solo usan desechables de uso único para todo"], correct: 0, explanation: "The level of decontamination required corresponds to the risk level. Hospitals perform invasive procedures requiring sterilization for all items contacting internal tissues. Esthetics involves primarily non-invasive services on intact skin — disinfection is the appropriate standard for most implements. Skin-piercing esthetics implements (lancets) do require sterile/single-use items." },
  { id: 140, question: "When a chemical disinfectant's contact time is specified as '10 minutes' on the label, this means:", question_es: "Cuando el tiempo de contacto de un desinfectante químico se especifica como '10 minutos' en la etiqueta, esto significa:", options: ["The implement must remain in contact with the disinfectant solution for the full 10 minutes while keeping the surface wet — the 10-minute period is when the chemical is actively killing pathogens, and cutting it short renders the disinfection ineffective", "The disinfectant must be applied for at least 10 seconds to have any effect", "The solution can be reused for 10 minutes after preparation before it must be replaced", "The implement must be soaked, then rinsed within 10 minutes to prevent corrosion"], options_es: ["El implemento debe permanecer en contacto con la solución desinfectante durante los 10 minutos completos manteniendo la superficie húmeda — el período de 10 minutos es cuando el químico está matando activamente los patógenos, y acortarlo hace que la desinfección sea inefectiva", "El desinfectante debe aplicarse durante al menos 10 segundos para tener algún efecto", "La solución puede reutilizarse durante 10 minutos después de la preparación antes de que deba reemplazarse", "El implemento debe remojarse y luego enjuagarse dentro de los 10 minutos para evitar la corrosión"], correct: 0, explanation: "Contact time (also called 'wet time' or 'dwell time') is the minimum duration that the disinfectant must remain in contact with a surface or implement while wet for it to achieve the efficacy claimed on the label. Shorter contact times may not kill the target pathogens. The label contact time is validated through EPA-required efficacy testing." },
  { id: 141, question: "An esthetics establishment must maintain infection control records including:", question_es: "Un establecimiento de estética debe mantener registros de control de infecciones que incluyan:", options: ["Documentation of disinfectant types and concentrations used, training records for all staff on infection control procedures, and records of any exposure incidents and post-exposure follow-up — these protect the establishment in case of TDLR inspection or legal action", "No records — infection control is a practical activity that does not require documentation", "Only a list of clients who had visible skin conditions at the time of service", "Financial records of disinfectant purchases only — no procedural documentation is required"], options_es: ["Documentación de los tipos y concentraciones de desinfectantes usados, registros de capacitación para todo el personal sobre los procedimientos de control de infecciones y registros de cualquier incidente de exposición y seguimiento post-exposición — estos protegen al establecimiento en caso de inspección de TDLR o acción legal", "Sin registros — el control de infecciones es una actividad práctica que no requiere documentación", "Solo una lista de clientes que tenían condiciones cutáneas visibles en el momento del servicio", "Solo registros financieros de compras de desinfectantes — no se requiere documentación de procedimientos"], correct: 0, explanation: "Documentation of infection control practices protects the establishment during TDLR inspections and provides evidence of compliance. Key records: disinfectant products used (with EPA registration numbers), staff training dates, exposure incident reports, and SDS for all chemical products. Documented training shows employees were properly trained on protocols." },
  { id: 142, question: "Milia (singular: milium) encountered during a facial esthetics service are:", question_es: "Los milios (singular: milio) encontrados durante un servicio facial de estética son:", options: ["Small, white keratin-filled cysts beneath the skin surface — estheticians may gently remove them using a sterile lancet and extractor, but only if trained and within their scope; improper technique risks infection and scarring", "Contagious viral lesions that must not be touched during any esthetics service", "Blackheads (open comedones) that require steam to open before extraction", "Sebaceous cysts requiring surgical removal — always refer to a physician"], options_es: ["Pequeños quistes llenos de queratina debajo de la superficie de la piel — los esteticistas pueden eliminarlos suavemente usando una lanceta estéril y un extractor, pero solo si están capacitados y dentro de su alcance; una técnica incorrecta arriesga infección y cicatrización", "Lesiones virales contagiosas que no deben tocarse durante ningún servicio de estética", "Puntos negros (comedones abiertos) que requieren vapor para abrirse antes de la extracción", "Quistes sebáceos que requieren extirpación quirúrgica — siempre derivar al médico"], correct: 0, explanation: "Milia are benign keratin cysts that appear as small white or yellowish bumps. Unlike blackheads, they have no follicle opening and cannot be extracted by squeezing. Removal requires a sterile lancet to create an opening, then gentle extraction. Proper technique is essential to avoid infection and scarring. Some states restrict milia extraction to physicians." },
  { id: 143, question: "A client who develops a skin infection after an esthetics service should be advised to:", question_es: "A un cliente que desarrolla una infección cutánea después de un servicio de estética se le debe aconsejar:", options: ["Seek medical attention promptly — a physician can diagnose the infection, prescribe appropriate treatment, and document the case; the esthetician should document the incident and review sanitation protocols", "Apply over-the-counter antiseptic cream and wait to see if it resolves on its own", "Return to the esthetics establishment immediately for additional treatments to address the infection", "Avoid all skin care products until the infection resolves without medical intervention"], options_es: ["Buscar atención médica de inmediato — un médico puede diagnosticar la infección, prescribir el tratamiento apropiado y documentar el caso; el esteticista debe documentar el incidente y revisar los protocolos de saneamiento", "Aplicar crema antiséptica de venta libre y esperar a ver si se resuelve por sí sola", "Regresar al establecimiento de estética de inmediato para tratamientos adicionales para abordar la infección", "Evitar todos los productos para el cuidado de la piel hasta que la infección se resuelva sin intervención médica"], correct: 0, explanation: "A post-service skin infection requires medical evaluation and treatment. The esthetician should: (1) recommend prompt physician care, (2) document the incident including client details, service performed, and products/implements used, (3) review sanitation protocols to identify any potential breach, and (4) notify TDLR if required. Attempting to treat the infection in the esthetics establishment is outside scope." },
  { id: 144, question: "The hepatitis B vaccine is recommended for estheticians because:", question_es: "La vacuna contra la hepatitis B se recomienda para los esteticistas porque:", options: ["Estheticians performing extractions and other skin-compromising services have occupational risk of bloodborne pathogen exposure — the HBV vaccine provides significant protection against the most easily transmitted bloodborne pathogen in esthetics settings", "The vaccine is required by Texas TDLR as a condition of obtaining an esthetics license", "The vaccine protects against all bloodborne pathogens including HIV and HCV", "The HBV vaccine is no longer recommended because HBV has been eradicated"], options_es: ["Los esteticistas que realizan extracciones y otros servicios que comprometen la piel tienen riesgo ocupacional de exposición a patógenos de transmisión sanguínea — la vacuna contra el VHB proporciona una protección significativa contra el patógeno de transmisión sanguínea más fácilmente transmitido en los entornos de estética", "La vacuna es requerida por TDLR de Texas como condición para obtener una licencia de estética", "La vacuna protege contra todos los patógenos de transmisión sanguínea incluidos el VIH y el VHC", "La vacuna contra el VHB ya no se recomienda porque el VHB ha sido erradicado"], correct: 0, explanation: "OSHA recommends (and employers must offer at no cost) the HBV vaccine series to workers with occupational bloodborne pathogen exposure risk. Estheticians performing extractions have this risk. The HBV vaccine is highly effective (>90%) against hepatitis B. There are no vaccines against HIV or HCV — standard precautions are the only protection against those." },
  { id: 145, question: "What is the role of the 'acid mantle' of the skin in infection control?", question_es: "¿Cuál es el papel del 'manto ácido' de la piel en el control de infecciones?", options: ["The acid mantle (a thin, slightly acidic film formed by sebum, sweat, and skin cell secretions at pH 4.5–5.5) inhibits the growth of many pathogenic bacteria and fungi — disrupting it through harsh alkaline cleansers reduces the skin's natural infection resistance", "The acid mantle is a product applied by estheticians — it is not a natural skin component", "The acid mantle only functions in hair care — it has no role in facial skin infection defense", "The acid mantle maintains skin hydration but has no antimicrobial function"], options_es: ["El manto ácido (una película delgada y ligeramente ácida formada por el sebo, el sudor y las secreciones de las células de la piel a pH 4.5–5.5) inhibe el crecimiento de muchas bacterias y hongos patógenos — perturbarlo a través de limpiadores alcalinos agresivos reduce la resistencia natural de la piel a las infecciones", "El manto ácido es un producto aplicado por los esteticistas — no es un componente natural de la piel", "El manto ácido solo funciona en el cuidado del cabello — no tiene ningún papel en la defensa de infecciones de la piel facial", "El manto ácido mantiene la hidratación de la piel pero no tiene función antimicrobiana"], correct: 0, explanation: "The acid mantle (pH 4.5–5.5) is the skin's first-line chemical defense. Many pathogenic organisms prefer neutral to alkaline pH and are inhibited by the skin's naturally acidic surface. Harsh alkaline soaps and products disrupt this protective barrier. Esthetics products formulated at the skin's natural pH help maintain this defense." },
  { id: 146, question: "During an esthetics service, maintaining a clean work field means:", question_es: "Durante un servicio de estética, mantener un campo de trabajo limpio significa:", options: ["Keeping the service area organized with clean implements on one side, used items immediately removed to the contaminated area, and all single-use items opened fresh at the start of each service — never crossing clean and contaminated zones during the service", "Keeping the service room aesthetically organized for a pleasant client experience", "Only changing the facial bed paper between each client — the work surface need not be disinfected until the end of the day", "Using the same implements throughout the service since the client's skin has already been contacted by them all"], options_es: ["Mantener el área de servicio organizada con implementos limpios a un lado, los artículos usados retirados inmediatamente al área contaminada y todos los artículos de uso único abiertos frescos al inicio de cada servicio — nunca cruzar las zonas limpias y contaminadas durante el servicio", "Mantener la sala de servicio estéticamente organizada para una experiencia agradable al cliente", "Solo cambiar el papel de la cama facial entre cada cliente — la superficie de trabajo no necesita desinfectarse hasta el final del día", "Usar los mismos implementos durante todo el servicio ya que la piel del cliente ya ha sido contactada por todos ellos"], correct: 0, explanation: "Maintaining a clean field throughout the service prevents cross-contamination. Once an implement contacts the client's skin, it is considered potentially contaminated and should not contact clean items (unused products, other clean implements). The discipline of keeping clean and contaminated zones separate during the entire service is a core infection control principle." },
  { id: 147, question: "Personal protective equipment (PPE) should be removed in which order after a service involving bloodborne pathogen risk?", question_es: "El equipo de protección personal (EPP) debe retirarse en qué orden después de un servicio que involucra riesgo de patógenos de transmisión sanguínea?", options: ["Gloves first (the most contaminated item), then any other PPE, then perform hand hygiene — removing gloves before other PPE reduces the risk of self-contamination during the removal process", "Eyewear first, then gown, then gloves last — gloves are the safest to leave on until last", "All PPE is removed simultaneously and discarded as a single unit", "PPE removal order is irrelevant — any order is equally safe"], options_es: ["Guantes primero (el artículo más contaminado), luego cualquier otro EPP, luego realizar higiene de manos — retirar los guantes antes que otro EPP reduce el riesgo de autocontaminación durante el proceso de remoción", "Gafas primero, luego bata, luego guantes al final — los guantes son los más seguros de dejar puestos hasta el final", "Todo el EPP se retira simultáneamente y se descarta como una sola unidad", "El orden de remoción del EPP es irrelevante — cualquier orden es igualmente seguro"], correct: 0, explanation: "Proper PPE removal sequence minimizes self-contamination: (1) gloves (most contaminated) — use glove-to-glove/skin-to-skin technique, (2) any protective eyewear (by the arms, not the lens), (3) gown (if worn), (4) perform hand hygiene. This sequence ensures the esthetician's bare skin doesn't contact the outer (contaminated) surface of the PPE." },
  { id: 148, question: "When is hand sanitizer (alcohol-based hand rub) an acceptable substitute for hand washing with soap and water in an esthetics setting?", question_es: "¿Cuándo es el desinfectante de manos (solución de alcohol) un sustituto aceptable para el lavado de manos con jabón y agua en un entorno de estética?", options: ["When hands are not visibly soiled — alcohol-based hand sanitizer (at least 60% alcohol) is effective for hand hygiene when hands appear clean, but soap and water MUST be used when hands are visibly dirty, after removing gloves, or after potential contact with blood", "Hand sanitizer is never acceptable — soap and water must always be used in esthetics settings", "Hand sanitizer is preferred over soap and water in all esthetics situations because it is more effective", "Hand sanitizer should only be used when a sink is not available — if a sink is accessible, sanitizer is not necessary"], options_es: ["Cuando las manos no están visiblemente sucias — el desinfectante de manos a base de alcohol (al menos 60% de alcohol) es efectivo para la higiene de manos cuando las manos parecen limpias, pero el jabón y el agua DEBEN usarse cuando las manos están visiblemente sucias, después de quitarse los guantes o después del posible contacto con sangre", "El desinfectante de manos nunca es aceptable — el jabón y el agua siempre deben usarse en los entornos de estética", "El desinfectante de manos es preferible al jabón y al agua en todas las situaciones de estética porque es más efectivo", "El desinfectante de manos solo debe usarse cuando no hay un lavabo disponible — si hay un lavabo accesible, el desinfectante no es necesario"], correct: 0, explanation: "CDC guidelines: soap and water are required when hands are visibly dirty/soiled, after blood/body fluid contact, after glove removal, after using the restroom, or when C. difficile spore contamination is possible. Alcohol hand sanitizer (≥60% alcohol) is appropriate for visibly clean hands between client contacts and is faster/less drying than repeated soap-and-water washing." },
  { id: 149, question: "In an esthetics establishment, the term 'decontamination area' refers to:", question_es: "En un establecimiento de estética, el término 'área de descontaminación' se refiere a:", options: ["A designated, separate area where used implements are brought, cleaned, and disinfected — kept apart from the clean storage area to prevent cross-contamination between dirty and clean implements", "The entire esthetics treatment room, which must be decontaminated between clients", "The area near the front desk where clients wait before services", "An area reserved exclusively for handling chemicals — implements are not decontaminated there"], options_es: ["Un área designada y separada donde se traen los implementos usados, se limpian y se desinfectan — separada del área de almacenamiento limpia para evitar la contaminación cruzada entre los implementos sucios y limpios", "Toda la sala de tratamiento de estética, que debe descontaminarse entre clientes", "El área cerca del mostrador de recepción donde los clientes esperan antes de los servicios", "Un área reservada exclusivamente para el manejo de químicos — los implementos no se descontaminan allí"], correct: 0, explanation: "Best practice in infection control is to have a dedicated decontamination area for processing used implements — a separate sink or counter where cleaning and disinfection occur. This prevents contaminated implements from being processed near clean items and creates a clear workflow: dirty implements in → clean implements out → stored in clean area." },
  { id: 150, question: "Which pathogens are classified as 'bloodborne pathogens' under OSHA's Bloodborne Pathogen Standard and are of primary concern to estheticians?", question_es: "¿Qué patógenos se clasifican como 'patógenos de transmisión sanguínea' bajo el Estándar de Patógenos de Transmisión Sanguínea de OSHA y son de principal preocupación para los esteticistas?", options: ["Human Immunodeficiency Virus (HIV), Hepatitis B Virus (HBV), and Hepatitis C Virus (HCV) — the three bloodborne pathogens most specifically addressed by OSHA's standard and most relevant to esthetics occupational risk", "Only influenza and common cold viruses — respiratory pathogens are the primary OSHA concern", "Only bacteria — OSHA's bloodborne pathogen standard does not cover viruses", "Fungal organisms only — they are the most common blood-transmitted pathogens in esthetics settings"], options_es: ["Virus de Inmunodeficiencia Humana (VIH), Virus de la Hepatitis B (VHB) y Virus de la Hepatitis C (VHC) — los tres patógenos de transmisión sanguínea más específicamente abordados por el estándar de OSHA y más relevantes para el riesgo ocupacional de estética", "Solo influenza y virus del resfriado común — los patógenos respiratorios son la principal preocupación de OSHA", "Solo bacterias — el estándar de patógenos de transmisión sanguínea de OSHA no cubre los virus", "Solo organismos fúngicos — son los patógenos de transmisión sanguínea más comunes en los entornos de estética"], correct: 0, explanation: "OSHA's Bloodborne Pathogen Standard was developed primarily to address HIV, HBV, and HCV — the three bloodborne pathogens with the greatest occupational transmission risk in healthcare and personal care settings. All three can potentially be transmitted through contaminated esthetics implements if proper standard precautions are not followed." },
]

let out = readFileSync(FILE, 'utf8')
out += Q.map(q => fmt(q)).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${Q.length} Infection Control (ids ${Q[0].id}–${Q[Q.length-1].id})`)
